pub fn assignNestedScopeSlots(allocator: std.mem.Allocator, module_scope: *js_ast.Scope, symbols: []js_ast.Symbol) js_ast.SlotCounts {
        var slot_counts = js_ast.SlotCounts{  };
        _ = &slot_counts;
        var sorted_members = std.array_list.Managed(u32).init(allocator);
        _ = &sorted_members;
        defer {
        _ = sorted_members.deinit();
        }
        const valid_slot: u32 = 0;
        var members = module_scope.members.valueIterator();
        _ = &members;
        while (members.next()) |member| {
            symbols[@as(usize, @intCast(member.ref.innerIndex()))].nested_scope_slot = valid_slot;
        }
        for (cp_iter_slice(module_scope.generated.slice())) |r| {
            _ = &r;
            symbols[@as(usize, @intCast(r.innerIndex()))].nested_scope_slot = valid_slot;
        }
        for (cp_iter_slice(module_scope.children.slice())) |child| {
            _ = &child;
            _ = slot_counts.unionMax(assignNestedScopeSlotsHelper(sorted_members, child, symbols, js_ast.SlotCounts{  }));
        }
        members = module_scope.members.valueIterator();
        while (members.next()) |member| {
            symbols[@as(usize, @intCast(member.ref.innerIndex()))].nested_scope_slot = js_ast.Symbol.invalid_nested_scope_slot;
        }
        for (cp_iter_slice(module_scope.generated.slice())) |r| {
            _ = &r;
            symbols[@as(usize, @intCast(r.innerIndex()))].nested_scope_slot = js_ast.Symbol.invalid_nested_scope_slot;
        }
        return slot_counts;
}

pub fn assignNestedScopeSlotsHelper(sorted_members: *std.array_list.Managed(u32), scope: *js_ast.Scope, symbols: []js_ast.Symbol, slot_to_copy: js_ast.SlotCounts) js_ast.SlotCounts {
        var slot = slot_to_copy;
        _ = &slot;
        {
            _ = sorted_members.clearRetainingCapacity();
            _ = ((sorted_members.ensureUnusedCapacity(scope.members.count())) catch unreachable);
            sorted_members.items.len = scope.members.count();
            var sorted_members_buf = sorted_members.items;
            _ = &sorted_members_buf;
            var members = scope.members.valueIterator();
            _ = &members;
            var i: usize = 0;
            _ = &i;
            while (members.next()) |member| {
                sorted_members_buf[cp_cast_int(usize, i)] = member.ref.innerIndex();
                i = (i + 1);
            }
            _ = std.sort.pdq(u32, sorted_members_buf, .{}, std.sort.asc(u32));
            for (cp_iter_slice(sorted_members_buf)) |inner_index| {
                _ = &inner_index;
                var symbol = (&symbols[@as(usize, @intCast(inner_index))]);
                _ = &symbol;
                const ns = symbol.slotNamespace();
                if (((ns != .must_not_be_renamed) and (symbol.nestedScopeSlot() == null))) {
                    symbol.nested_scope_slot = slot.slots.get(ns);
                    (slot.slots.getPtr(ns)).* = ((slot.slots.getPtr(ns)).* + 1);
                }
            }
        }
        for (cp_iter_slice(scope.generated.slice())) |r| {
            _ = &r;
            var symbol = (&symbols[@as(usize, @intCast(r.innerIndex()))]);
            _ = &symbol;
            const ns = symbol.slotNamespace();
            if (((ns != .must_not_be_renamed) and (symbol.nestedScopeSlot() == null))) {
                symbol.nested_scope_slot = slot.slots.get(ns);
                (slot.slots.getPtr(ns)).* = ((slot.slots.getPtr(ns)).* + 1);
            }
        }
        if (scope.label_ref) |label_ref| {
            _ = &label_ref;
            var symbol = (&symbols[@as(usize, @intCast(label_ref.innerIndex()))]);
            _ = &symbol;
            const ns = js_ast.Symbol.SlotNamespace.label;
            symbol.nested_scope_slot = slot.slots.get(ns);
            (slot.slots.getPtr(ns)).* = ((slot.slots.getPtr(ns)).* + 1);
        }
        var slot_counts = slot;
        _ = &slot_counts;
        for (cp_iter_slice(scope.children.slice())) |child| {
            _ = &child;
            _ = slot_counts.unionMax(assignNestedScopeSlotsHelper(sorted_members, child, symbols, slot));
        }
        return slot_counts;
}

pub fn computeInitialReservedNames(allocator: std.mem.Allocator, output_format: bun.options.Format) !bun.StringHashMapUnmanaged(u32) {
        if (comptime bun.Environment.isWasm) {
            _ = unreachable;
        }
        var names: bun.StringHashMapUnmanaged(u32) = .{};
        _ = &names;
        const extras: struct { []const u8, []const u8 } = .{ "Promise", "Require" };
        const cjs_names: struct { []const u8, []const u8 } = .{ "exports", "module" };
        const cjs_names_len: u32 = (if ((output_format == .cjs)) cjs_names.len else 0);
        _ = try names.ensureTotalCapacityContext(allocator, (cjs_names_len + @as(u32, @truncate((((JSLexer.Keywords.keys().len + JSLexer.StrictModeReservedWords.keys().len) + 1) + extras.len)))), bun.StringHashMapContext{  });
        for (cp_iter_slice(JSLexer.Keywords.keys())) |keyword| {
            _ = &keyword;
            _ = names.putAssumeCapacity(keyword, 1);
        }
        for (cp_iter_slice(JSLexer.StrictModeReservedWords.keys())) |keyword| {
            _ = &keyword;
            _ = names.putAssumeCapacity(keyword, 1);
        }
        if ((output_format == .cjs)) {
            inline for (cjs_names) |name| {
                _ = names.putAssumeCapacity(name, 1);
            }
        }
        inline for ((comptime extras)) |extra| {
            _ = names.putAssumeCapacity(extra, 1);
        }
        return names;
}

pub fn computeReservedNamesForScope(scope: *js_ast.Scope, symbols: *const js_ast.Symbol.Map, names_: *bun.StringHashMapUnmanaged(u32), allocator: std.mem.Allocator) void {
        var names = names_.*;
        _ = &names;
        defer {
        names_.* = names;
        }
        var member_iter = scope.members.valueIterator();
        _ = &member_iter;
        while (member_iter.next()) |member| {
            const symbol = (symbols.get(member.ref)).?;
            if (((symbol.kind == .unbound) or symbol.must_not_be_renamed)) {
                _ = ((names.put(allocator, symbol.original_name, 1)) catch unreachable);
            }
        }
        for (cp_iter_slice(scope.generated.slice())) |r| {
            _ = &r;
            const symbol = (symbols.get(r)).?;
            if (((symbol.kind == .unbound) or symbol.must_not_be_renamed)) {
                _ = ((names.put(allocator, symbol.original_name, 1)) catch unreachable);
            }
        }
        if (scope.contains_direct_eval) {
            for (cp_iter_slice(scope.children.slice())) |child| {
                _ = &child;
                if (child.contains_direct_eval) {
                    names_.* = names;
                    _ = computeReservedNamesForScope(child, symbols, (&names), allocator);
                }
            }
        }
}
